      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "THIP was reported to cross the human BBB rapidly despite a polar/zwitterionic structure, suggesting polar small molecules can access the CNS; however, the record's SMILES is inconsistent and the query is dicationic rather than zwitterionic, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "A raloxifene-like piperidine phenol (4g) had log BB -0.77 in rats after oral dosing, showing that piperidine-containing polar/large molecules can have poor brain exposure; this supports fail for the dicationic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Raloxifene, which contains a piperidine-ethoxy group, has brain concentration approximately 1/100 of blood, reinforcing that polar/large piperidine-containing structures can be poor CNS penetrants.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "AH-9700, a lipophilic piperidine tetralin, had a brain/plasma ratio of approximately 100 in rats, but its large lipophilic scaffold is absent in the query, limiting transferability to the dicationic guanidine-azocane.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ro 03-8799, a basic piperidine-containing radiosensitizer, achieved 23% CSF/plasma in humans, indicating some CNS access for basic amines; however, the query is dicationic and lacks the nitroimidazole/amphiphilic character, so this is weakly contradictory.",
      "evidence_role": "contradictory"
    }
